<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { CheckCircle2, CopyPlus, Download, History, Play, RefreshCw, RotateCcw, Save, Trash2, Upload } from '@lucide/vue'
import { api } from '../services/http'
import SectionHeader from './SectionHeader.vue'
const library=ref<any>({profiles:[],base_templates:{}});const profiles=ref<any>({profiles:[]});const override=ref<any>({content:'',enabled:false});const selectedId=ref('');const status=ref('');const failed=ref(false);const history=ref<any[]>([]);const importText=ref('')
const create=reactive({name:'',description:'',source_id:'stable'});const editor=reactive<any>({id:'',name:'',description:'',editable:false,enabled:true,editor_mode:'modules',simple_policy:{},pipelines:{},trading_system:'',trading_user:'',evolution_system:'',evolution_user:'',note:'Vue 管理后台更新'})
const selected=computed(()=>profiles.value.profiles?.find((x:any)=>x.id===selectedId.value))
function note(t:string,e=false){status.value=t;failed.value=e;setTimeout(()=>status.value='',4500)}
function apply(p:any){if(!p)return;selectedId.value=p.id;Object.assign(editor,{id:p.id,name:p.name,description:p.description||'',editable:Boolean(p.editable),enabled:p.enabled!==false,editor_mode:p.editor_mode||'modules',simple_policy:p.simple_policy||{},pipelines:p.pipelines||{},trading_system:p.trading_system||'',trading_user:p.trading_user||'',evolution_system:p.evolution_system||'',evolution_user:p.evolution_user||'',note:'Vue 管理后台更新'});history.value=[]}
async function load(){try{const [l,p,o]:any=await Promise.all([api('/api/v1/admin/prompt-library'),api('/api/v1/admin/prompt-profiles'),api('/api/v1/admin/prompts')]);library.value=l;profiles.value=p;override.value=o;apply(p.profiles.find((x:any)=>x.id===p.active_profile_id)||p.profiles[0])}catch(e:any){note(e.message,true)}}
async function activate(id:string){try{await api(`/api/v1/admin/prompt-profiles/${id}/activate`,{method:'POST',body:'{}'});note('提示词方案已启用');await load()}catch(e:any){note(e.message,true)}}
async function createProfile(){try{const d:any=await api('/api/v1/admin/prompt-profiles',{method:'POST',body:JSON.stringify(create)});create.name='';create.description='';note('自定义方案已创建');await load();apply(d.profile)}catch(e:any){note(e.message,true)}}
function payload(){return {name:editor.name,description:editor.description,enabled:editor.enabled,editor_mode:editor.editor_mode,simple_policy:editor.simple_policy||{},pipelines:editor.pipelines||{},trading_system:editor.trading_system,evolution_system:editor.evolution_system,trading_user:editor.trading_user,evolution_user:editor.evolution_user,note:editor.note}}
async function save(){if(!editor.editable)return note('内置方案不可直接修改，请先复制创建自定义方案',true);try{await api(`/api/v1/admin/prompt-profiles/${editor.id}`,{method:'PUT',body:JSON.stringify(payload())});note('提示词方案已保存');await load()}catch(e:any){note(e.message,true)}}
async function validate(){try{const d:any=await api('/api/v1/admin/prompt-profiles/validate',{method:'POST',body:JSON.stringify(payload())});note(d.valid===false?`验证失败：${(d.errors||[]).join('；')}`:`验证通过${d.warnings?.length?'：'+d.warnings.join('；'):''}`,d.valid===false)}catch(e:any){note(e.message,true)}}
async function remove(){if(!editor.editable||!confirm(`确认删除方案 ${editor.name}？`))return;try{await api(`/api/v1/admin/prompt-profiles/${editor.id}`,{method:'DELETE'});note('方案已删除');await load()}catch(e:any){note(e.message,true)}}
async function loadHistory(){try{const d:any=await api(`/api/v1/admin/prompt-profiles/${editor.id}/history`);history.value=d.history||[]}catch(e:any){note(e.message,true)}}
async function rollback(rev:any){if(!confirm(`确认回滚到 ${rev.id||rev.revision_id}？`))return;try{await api(`/api/v1/admin/prompt-profiles/${editor.id}/rollback`,{method:'POST',body:JSON.stringify({revision_id:rev.id||rev.revision_id})});note('回滚完成');await load()}catch(e:any){note(e.message,true)}}
async function exportProfile(){try{const d:any=await api(`/api/v1/admin/prompt-profiles/${editor.id}/export`);const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`r20-prompt-${editor.id}.json`;a.click();URL.revokeObjectURL(a.href)}catch(e:any){note(e.message,true)}}
async function saveOverride(){try{await api('/api/v1/admin/prompts',{method:'PUT',body:JSON.stringify({content:override.value.content||''})});note(override.value.content?'管理员覆盖层已保存':'管理员覆盖层已清除');await load()}catch(e:any){note(e.message,true)}}
async function importProfile(){try{const raw=JSON.parse(importText.value);const d:any=await api('/api/v1/admin/prompt-profiles/import',{method:'POST',body:JSON.stringify({payload:raw,name_override:''})});importText.value='';note('方案已导入');await load();apply(d.profile)}catch(e:any){note(e.message,true)}}
onMounted(load)
</script>
<template><div class="space-y-4"><div v-if="status" class="panel border-l-4 p-3 text-xs" :class="failed?'text-loss':'text-profit'">{{status}}</div><section class="panel p-4 sm:p-5"><SectionHeader title="管理员 Prompt 覆盖层" subtitle="直接叠加到交易 System Prompt，清空后恢复默认"><template #actions><button class="btn btn-primary" @click="saveOverride"><Save :size="14"/>保存覆盖层</button></template></SectionHeader><textarea v-model="override.content" class="input min-h-40 font-mono text-[11px] leading-6" placeholder="留空表示不启用覆盖层"></textarea><div class="mt-2 data-pill" :class="override.enabled?'data-pill-warning':'data-pill-profit'">{{override.enabled?'覆盖层已启用':'当前使用基础 Prompt'}}</div></section><section class="panel p-4 sm:p-5"><SectionHeader title="提示词方案库" subtitle="创建、验证、启用、回滚、导入和导出" :count="profiles.profiles?.length||0"><template #actions><button class="btn" @click="load"><RefreshCw :size="14"/>刷新</button></template></SectionHeader><div class="grid gap-2.5 sm:grid-cols-2 xl:grid-cols-3"><button v-for="p in profiles.profiles||[]" :key="p.id" class="subpanel key-card p-4 text-left" :class="p.id===profiles.active_profile_id?'key-card-profit':'key-card-brand'" @click="apply(p)"><div class="flex justify-between gap-2"><b>{{p.name}}</b><span class="badge" :class="p.id===profiles.active_profile_id?'badge-profit':''">{{p.id===profiles.active_profile_id?'当前启用':p.editable?'自定义':'内置'}}</span></div><p class="mt-2 line-clamp-2 text-[10px] leading-5 muted">{{p.description}}</p><div class="mt-3 flex gap-2"><span class="data-pill">{{p.id}}</span><button v-if="p.id!==profiles.active_profile_id" class="btn !min-h-8 !py-1" @click.stop="activate(p.id)"><Play :size="12"/>启用</button></div></button></div></section><div class="grid gap-4 xl:grid-cols-[.34fr_.66fr]"><div class="space-y-4"><section class="panel p-4"><SectionHeader title="创建自定义方案"/><label class="label">名称</label><input v-model="create.name" class="input mb-3"/><label class="label">描述</label><textarea v-model="create.description" class="input min-h-24"></textarea><label class="label mt-3">复制来源</label><select v-model="create.source_id" class="input"><option v-for="p in profiles.profiles||[]" :value="p.id">{{p.name}}</option></select><button class="btn btn-primary mt-3" @click="createProfile"><CopyPlus :size="14"/>创建副本</button></section><section class="panel p-4"><SectionHeader title="导入方案"/><textarea v-model="importText" class="input min-h-36 font-mono text-xs" placeholder="粘贴导出的 JSON"></textarea><button class="btn mt-3" @click="importProfile"><Upload :size="14"/>导入</button></section><section v-if="history.length" class="panel p-4"><SectionHeader title="修订历史" :count="history.length"/><div class="space-y-2"><div v-for="h in history" class="subpanel p-3"><div class="flex justify-between"><b class="text-xs">{{h.created_at||h.timestamp||h.id}}</b><button class="btn !min-h-8 !py-1" @click="rollback(h)"><RotateCcw :size="12"/>回滚</button></div><p class="mt-1 text-[10px] muted">{{h.note||'历史修订'}}</p></div></div></section></div><section class="panel p-4 sm:p-5"><SectionHeader :title="editor.name||'方案编辑器'" :subtitle="editor.editable?'编辑四条真实 Prompt 管线':'内置方案只读，可复制后编辑'"><template #actions><div class="flex flex-wrap gap-2"><button class="btn" @click="validate"><CheckCircle2 :size="14"/>验证</button><button class="btn" @click="loadHistory"><History :size="14"/>历史</button><button class="btn" @click="exportProfile"><Download :size="14"/>导出</button><button v-if="editor.editable" class="btn btn-danger" @click="remove"><Trash2 :size="14"/></button><button v-if="editor.editable" class="btn btn-primary" @click="save"><Save :size="14"/>保存</button></div></template></SectionHeader><div class="grid gap-3 sm:grid-cols-2"><div><label class="label">方案名称</label><input v-model="editor.name" class="input" :disabled="!editor.editable"/></div><div><label class="label">启用状态</label><select v-model="editor.enabled" class="input" :disabled="!editor.editable"><option :value="true">启用</option><option :value="false">停用</option></select></div></div><label class="label mt-3">描述</label><input v-model="editor.description" class="input" :disabled="!editor.editable"/><div class="mt-4 space-y-4"><div v-for="item in [{k:'trading_system',n:'交易 System'},{k:'trading_user',n:'交易 User'},{k:'evolution_system',n:'自进化 System'},{k:'evolution_user',n:'自进化 User'}]" :key="item.k"><label class="label">{{item.n}} · {{String(editor[item.k]||'').length}} 字符</label><textarea v-model="editor[item.k]" class="input min-h-44 font-mono text-[11px] leading-6" :disabled="!editor.editable"></textarea></div></div></section></div></div></template>
